const deepCloneObject = require('../../../src/options/clone.js')

describe('deepCloneObject', () => {
  test('should clone a simple object with primitive values', () => {
    const original = { a: 1, b: 'test', c: true }
    const cloned = deepCloneObject(original)

    expect(cloned).toEqual(original)
    expect(cloned).not.toBe(original)
  })

  test('should perform deep cloning of nested objects', () => {
    const original = { 
      a: 1, 
      nested: { 
        b: 2, 
        deeper: { 
          c: 3 
        } 
      } 
    }
    const cloned = deepCloneObject(original)

    expect(cloned).toEqual(original)
    expect(cloned.nested).not.toBe(original.nested)
    expect(cloned.nested.deeper).not.toBe(original.nested.deeper)
  })

  test('should clone objects with arrays', () => {
    const original = { 
      a: 1, 
      arr: [1, 2, { b: 3 }] 
    }
    const cloned = deepCloneObject(original)

    expect(cloned).toEqual(original)
    expect(cloned.arr).not.toBe(original.arr)
    expect(cloned.arr[2]).not.toBe(original.arr[2])
  })

  test('should preserve property descriptors', () => {
    const original = {}
    Object.defineProperty(original, 'readOnly', {
      value: 'value',
      writable: false,
      enumerable: true,
      configurable: false
    })

    Object.defineProperty(original, 'writable', {
      value: 'value',
      writable: true,
      enumerable: true,
      configurable: true
    })

    const cloned = deepCloneObject(original)

    const readOnlyDescriptor = Object.getOwnPropertyDescriptor(cloned, 'readOnly')
    const writableDescriptor = Object.getOwnPropertyDescriptor(cloned, 'writable')

    expect(readOnlyDescriptor.value).toBe('value')
    expect(readOnlyDescriptor.writable).toBe(false)
    expect(readOnlyDescriptor.enumerable).toBe(true)
    expect(readOnlyDescriptor.configurable).toBe(false)

    expect(writableDescriptor.value).toBe('value')
    expect(writableDescriptor.writable).toBe(true)
    expect(writableDescriptor.enumerable).toBe(true)
    expect(writableDescriptor.configurable).toBe(true)
  })

  test('should handle symbol keys', () => {
    const sym = Symbol('test')
    const original = {
      a: 1,
      [sym]: 'symbol value'
    }

    const cloned = deepCloneObject(original)

    expect(cloned.a).toBe(1)
    expect(cloned[sym]).toBe('symbol value')
    expect(Object.getOwnPropertySymbols(cloned)).toHaveLength(1)
  })

  test('should handle empty objects', () => {
    const original = {}
    const cloned = deepCloneObject(original)

    expect(cloned).toEqual({})
    expect(cloned).not.toBe(original)
  })

  test('should clone objects with null prototype', () => {
    const original = Object.create(null)
    original.a = 1
    original.b = { c: 2 }

    const cloned = deepCloneObject(original)

    expect(cloned).toEqual(original)
    expect(Object.getPrototypeOf(cloned)).toBe(null)
    expect(cloned.b).not.toBe(original.b)
  })
})

