const normalizePluginsOpt = (ParentError, plugins = []) => {
  if (!Array.isArray(plugins)) {
    throw new TypeError(
      `The "plugins" option of "${ParentError.name}.subclass()" must be an array: ${plugins}`,
    )
  }

  return plugins
}

